$('detailtitle').textContent=s.person?people()[0].nome:'Referências do grupo';const detail=detailed();$('detailcount').textContent=`${detail.length} referência(s) · exibindo ${Math.min(limit,detail.length)}. O filtro de categoria se aplica às referências e ao relatório Word.`;$('refs').innerHTML=detail.slice(0,limit).map(r=>`<article class="reference"><div class="tag prod-${groupClass(r.grupo)}">${esc(r.grupo)} · ${esc(r.tipo)} · ${r.ano}</div><p>${esc(r.referencia_original)}</p><a href="${r.fonte}" target="_blank" rel="noopener">${esc(r.docente)} · Ver currículo Lattes ↗</a></article>`).join('')||(people().some(p=>p.status_coleta==='pendente')?'<p class="empty">Coleta pendente. O currículo ainda não foi incorporado; as contagens não são zero. Acesse o Lattes, conclua a verificação de segurança e importe o HTML salvo.</p>':'<p class="empty">Nenhum registro encontrado para esta seleção.</p>');$('more').hidden=limit>=detail.length;
